import {SUPPORTED,RULES,MODIFIERS,rng,pick,eligible,validateTeam,autoTeam,simulate} from './engine.js';
import {imageURL,normalize,ownedLevel,isBattleCard,sanitizeCollection,sanitizeCollectionRun} from './data.js';
import {STARTER_LIMIT,starterRoster,rosterError,ensureRoster,recruitmentOffers,recruitCard,recruitPrice} from './roster.js';
import {REALMS,NODE_TYPES,TOKENS,createRun,availableNodes,rewardFor,rerollNode,completeNode,nextAct,battleMana,graftCard,enemyFor,mysteryOutcome,claimVictory,finalizeRecruitment,campBoon,suggestLineup,hasLegalLineup} from './run.js';
const $=s=>document.querySelector(s), app=$('#app');
const ELEMENTS={Red:'Fire',Blue:'Water',Green:'Earth',White:'Life',Black:'Death',Gold:'Dragon',Gray:'Neutral'};
const COLORS={Fire:'#e58e75',Water:'#7fbad8',Earth:'#9ac095',Life:'#dec798',Death:'#b59ad5',Dragon:'#d6ad62',Neutral:'#b1b8c7'};
const SYMBOLS={Fire:'♨',Water:'≈',Earth:'♧',Life:'☼',Death:'☾',Dragon:'♜',Neutral:'◇'};
const RARITIES=['','Common','Rare','Epic','Legendary'];
let details=[],settings={},cards=[],foundation=[],run=null,profile={completed:0,runs:[]},collection=null;
let screen='welcome',tab='expedition',team=[],archon=null,paired='Fire',filter='all',search='',modal=null,importBusy=false,importError='',replayIndex=0,replayTimer=null,replaySpeed=1,collectionPage=0,lastRenderView=null;
const safe=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=(name,size=18)=>{const p={map:'<path d="m3 5 6-2 6 2 6-2v16l-6 2-6-2-6 2V5Z"/><path d="M9 3v16m6-14v16"/>',cards:'<rect x="6" y="3" width="14" height="18" rx="2"/><path d="M3 7v12a2 2 0 0 0 2 2m5-13h6m-6 4h6m-6 4h3"/>',book:'<path d="M12 5C8 2 4 3 2 4v15c3-1 6-1 10 1 4-2 7-2 10-1V4c-2-1-6-2-10 1Zm0 0v15"/>',arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',back:'<path d="M19 12H5m6-6-6 6 6 6"/>',shard:'<path d="m12 2 7 9-7 11-7-11 7-9Z"/><path d="m5 11 7 3 7-3M12 2v20"/>',token:'<circle cx="12" cy="12" r="9"/><path d="m12 6 4 6-4 6-4-6 4-6Z"/>',help:'<circle cx="12" cy="12" r="9"/><path d="M9 9a3 3 0 1 1 5 2c-2 1-2 2-2 3m0 3v.1"/>',check:'<path d="m5 12 4 4L19 6"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',sword:'<path d="m14 3 7 0v7L8 21l-5-5L14 3Zm-7 9 5 5M3 21l4-4"/>',shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6l8-3Z"/>',heart:'<path d="M12 20 3 11C-2 5 6 0 12 7c6-7 14-2 9 4l-9 9Z"/>',speed:'<path d="m13 2-9 12h7l-1 8 10-12h-7l0-8Z"/>',mana:'<path d="M12 2S4 10 4 15a8 8 0 0 0 16 0c0-5-8-13-8-13Z"/>',play:'<path d="m7 3 14 9-14 9V3Z"/>',pause:'<path d="M7 4v16M17 4v16"/>',reroll:'<path d="M20 7V3m0 4h-4M4 17v4m0-4h4M4 8a8 8 0 0 1 14-3l2 2M4 17l2 2a8 8 0 0 0 14-3"/>',wallet:'<rect x="3" y="5" width="18" height="15" rx="2"/><path d="M3 8h18m-5 5h5m-5 3h5M6 5V3h12"/>'}[name]||'<circle cx="12" cy="12" r="8"/>';
  return `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${p}</svg>`;};
function readStore(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback;}catch{return fallback;}}
function save(){try{if(run)localStorage.setItem('riftwalker.run.v1',JSON.stringify(run));localStorage.setItem('riftwalker.guest.v1',JSON.stringify(profile));if(collection)localStorage.setItem('riftwalker.collection.v1',JSON.stringify(collection));}catch{toast('Device storage is unavailable. Keep this tab open to preserve your run.');}}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),3500);}
const byId=id=>cards.find(c=>c.id===Number(id));
function sourcePool(){return run?.mode==='collection'?(run.collectionSnapshot?.cards||collection?.cards||foundation):foundation;}
function rosterSource(){return sourcePool().filter(c=>c.type==='Monster'||c.type==='Summoner'&&unlocked(c.element));}
function pool(){const source=sourcePool();return run?.rosterLocked?source.filter(c=>run.rosterIds.includes(c.id)):source;}
function archons(){return pool().filter(c=>c.type==='Summoner');}
function unlocked(element){return run?.mode==='collection'||['Fire','Earth','Life'].includes(element)||element==='Water'&&profile.completed>=1||element==='Death'&&profile.completed>=2||element==='Dragon'&&profile.completed>=3;}
function permitted(c){return c.element==='Neutral'||c.element===archon?.element||c.element===archon?.secondary||['Dragon','Neutral'].includes(archon?.element)&&c.element===paired;}
function monsters(){return pool().filter(c=>c.type==='Monster'&&permitted(c));}
function grafted(c){return graftCard(run,c);}
function cap(){return battleMana(run);}
function setArchon(id){archon=archons().find(c=>c.id===Number(id));team=[];run.draft=[];if(archon)run.archonId=archon.id;save();}
function resetDraft(){archon=archons().find(c=>c.id===run.archonId&&unlocked(c.element))||archons().find(c=>unlocked(c.element));team=[];paired=run.paired||'Fire';filter='all';search='';run.pending=null;run.draft=[];save();}
function render(){const renderView=tab==='expedition'?screen:tab;const scrollToTop=renderView!==lastRenderView;lastRenderView=renderView;clearInterval(replayTimer);replayTimer=null;app.innerHTML=header()+`<main>${tab==='collection'?collectionView():tab==='journal'?journalView():view()}</main>`+footer()+(modal?modalView():'');bind();if(scrollToTop)window.scrollTo(0,0);if(screen==='replay'&&tab==='expedition'&&!modal&&replayIndex<run.pending.events.length-1)startReplay();}
function header(){return `<header class="topbar"><button class="brand" data-action="home"><span class="brand-symbol">✧</span><span><small>SPLINTERLANDS</small><strong>RIFT WALKER</strong></span></button><nav aria-label="Main navigation">${[['expedition','map','Expedition'],['collection','cards','Collection'],['journal','book','Chronicle']].map(([key,i,label])=>`<button class="nav-button ${tab===key?'active':''}" data-tab="${key}">${icon(i)}<span>${label}</span></button>`).join('')}</nav><div class="header-right"><span class="prototype">PREVIEW 0.1</span><button class="icon-button" data-action="guide" aria-label="How to play">${icon('help',21)}</button><button class="account-button" data-action="import">${icon('wallet')}<span>${safe(run?.mode==='collection'?run.username:'Guest explorer')}</span><span class="status-dot"></span></button></div></header>`;}
function footer(){return `<footer><span><span class="status-dot"></span> ${run?.mode==='collection'?'Public collection · read only':location.hostname.endsWith('.github.io')?'Foundation collection · online preview':'Foundation collection · local sandbox'}</span><span>Independent fan prototype <span class="footer-divider">/</span> Progress saved to this device</span><button data-action="guide">Field guide ${icon('arrow',13)}</button></footer>`;}
function resources(){return `<div class="resource-bar"><div class="act-progress">${run.realms.map((realm,i)=>`<span class="act-step ${i===run.act?'current':i<run.act?'done':''}"><span>${i<run.act?'✓':`0${i+1}`}</span>${realm}<small>${i===run.act?'CURRENT ACT':i<run.act?'CLEARED':'UNEXPLORED'}</small></span>`).join('<span class="act-line"></span>')}</div><div class="resources"><div class="resource purple">${icon('token',23)}<span><strong>${run.tokens}</strong><small>RIFT TOKENS</small></span></div><div class="resource gold">${icon('shard',23)}<span><strong>${run.shards}</strong><small>RIFT SHARDS</small></span></div><button class="inventory-button" data-action="inventory">${icon('cards')}<span>Satchel</span><b>${run.inventory.length+Object.keys(run.grafts).length}</b></button>${run.rosterLocked?`<button class="inventory-button" data-action="view-roster">${icon('cards')}<span>Roster</span><b>${run.rosterIds.length}</b></button>`:''}</div></div>`;}
function view(){if(!run||screen==='welcome')return welcomeView();if(screen==='roster')return resources()+rosterView();if(screen==='recruit')return resources()+recruitView();if(screen==='map')return resources()+mapView();if(screen==='draft')return resources()+draftView();if(screen==='replay')return resources()+replayView();if(screen==='result')return resources()+resultView();if(screen==='shop')return resources()+shopView();if(screen==='camp'||screen==='intermission')return resources()+campView();if(screen==='mystery')return resources()+mysteryView();if(screen==='end')return endView();return welcomeView();}
function welcomeView(){return `<section class="welcome"><div class="welcome-content"><p class="eyebrow"><span></span> A SPLINTERLANDS ROGUELIKE EXPEDITION</p><h1>Beyond the veil.<br>A new <em>adventure.</em></h1><p class="intro">Your collection. Uncharted realms. One expedition.<br>Choose your expedition roster, follow your path, and face the Guardians waiting on the other side.</p><div class="welcome-actions">${run?.status==='active'?`<button class="button primary" data-action="resume">Continue expedition ${icon('arrow')}</button>`:`<button class="button primary" data-action="begin">Enter the rift ${icon('arrow')}</button>`}<button class="button secondary" data-action="import">${icon('wallet')} Use my collection</button></div><div class="welcome-note"><span class="status-dot"></span> Play free with the official Foundation collection</div><div class="welcome-features"><div>${icon('map',25)}<strong>3 shifting realms</strong><span>Choose your own path</span></div><div>${icon('cards',25)}<strong>Your cards, your strategy</strong><span>Real stats. Familiar abilities.</span></div><div>${icon('token',25)}<strong>A second chance</strong><span>Lose a battle. Reroll the rift.</span></div></div></div><div class="portal-scene" aria-hidden="true"><div class="portal-orbit orbit-one"></div><div class="portal-orbit orbit-two"></div><div class="portal-core"><span>✧</span></div><div class="portal-base"></div><div class="floating-rune rune-one">◇</div><div class="floating-rune rune-two">✧</div><div class="floating-rune rune-three">⋄</div><p>THE RIFT IS CALLING</p></div></section><div class="welcome-bottom"><span>01 <b>Choose your roster</b></span><span>02 <b>Explore the branching map</b></span><span>03 <b>Challenge the Guardians</b></span><button data-action="guide">Learn the rules ${icon('arrow',15)}</button></div>`;}
function rosterView(){
  const source=rosterSource(),selected=source.filter(c=>run.rosterIds.includes(c.id)),error=rosterError(run.rosterIds,source);
  const shown=source.filter(c=>filter==='all'||filter==='archons'&&c.type==='Summoner'||filter==='selected'&&run.rosterIds.includes(c.id)||c.element===filter).filter(c=>c.name.toLowerCase().includes(search.toLowerCase())).sort((a,b)=>(a.type==='Summoner'?0:1)-(b.type==='Summoner'?0:1)||a.mana-b.mana||a.id-b.id);
  return `<section class="page-heading"><div><p class="eyebrow">YOUR COMPANIONS FOR THE JOURNEY</p><h1>Build your expedition roster</h1><p>Choose up to ${STARTER_LIMIT} cards, including at least one Archon. Recruit more as you explore.</p></div></section><section class="panel roster-summary"><div class="section-title"><span><b>STARTING ROSTER</b><small>${selected.length} / ${STARTER_LIMIT} cards · ${selected.filter(c=>c.type==='Summoner').length} Archons</small></span><div><button class="text-button" data-action="clear-roster">Clear</button><button class="mini-button" data-action="suggest-roster">Suggest roster</button></div></div><div class="roster-chips">${selected.map(c=>`<button data-roster-card="${c.id}" title="Remove ${safe(c.name)}"><span style="color:${COLORS[c.element]}">${SYMBOLS[c.element]}</span> ${safe(c.name)} <span>×</span></button>`).join('')||'<p>Select your companions below.</p>'}</div><p class="fine-print">Deploy up to six units per battle, within the node’s mana cap. Bring different attack types and mana costs for changing rulesets. Health resets after every battle; grafts stay attached for their stated duration.</p></section><section class="panel full-collection"><div class="collection-toolbar"><div class="filter-row">${['all','selected','archons','Fire','Water','Earth','Life','Death','Dragon','Neutral'].map(e=>`<button class="filter-button ${filter===e?'active':''}" data-filter="${e}">${e==='all'?'All cards':e==='selected'?'Selected':e==='archons'?'Archons':e}</button>`).join('')}</div><label class="search-field"><span>⌕</span><input id="card-search" value="${safe(search)}" placeholder="Find a companion…" aria-label="Find a companion"></label></div><div class="card-grid collection-grid">${shown.slice(collectionPage*48,(collectionPage+1)*48).map(c=>cardView(c,{roster:true})).join('')||'<div class="empty-message">No cards match these filters.</div>'}</div>${shown.length>48?`<div class="pagination"><button class="mini-button" data-page="${collectionPage-1}" ${collectionPage===0?'disabled':''}>Previous</button><span>Page ${collectionPage+1} of ${Math.ceil(shown.length/48)}</span><button class="mini-button" data-page="${collectionPage+1}" ${(collectionPage+1)*48>=shown.length?'disabled':''}>Next</button></div>`:''}</section><div class="roster-ready panel"><span>${error||'Your companions are ready. The roster locks when you enter the rift.'}</span><button class="button primary" data-action="lock-roster" ${error?'disabled':''}>Enter with this roster ${icon('arrow')}</button></div>`;
}
function recruitmentCards(kind){
  const offers=recruitmentOffers(run,rosterSource(),kind);
  return offers.map(c=>{const recruited=run.rosterIds.includes(c.id),price=kind==='merchant'?recruitPrice(c):0;return `<article class="recruit-card panel">${cardView(c)}<button class="button secondary full" data-recruit="${c.id}" data-kind="${kind}" ${recruited||run.shards<price?'disabled':''}>${recruited?'Recruited':price?`Recruit · ${price} shards`:`Recruit ${safe(c.name)}`}</button><small>${c.type==='Summoner'?'Archon · opens its elements':'Unit · joins your expedition roster'}</small></article>`;}).join('');
}
function recruitView(){const event=run.recruitment.kind==='event';return `<section class="page-heading"><div><p class="eyebrow">${event?'A COMPANION ON THE ROAD':'VICTORY BRINGS NEW POSSIBILITIES'}</p><h1>Choose a new companion</h1><p>Recruit one card for free. It stays in your roster for the rest of this expedition.</p></div><button class="button secondary" data-action="skip-recruit">Continue without recruiting ${icon('arrow')}</button></section><div class="recruit-grid">${recruitmentCards(run.recruitment.kind)||'<div class="empty-message">Every available companion has already joined you.</div>'}</div>`;}
function openRecruitment(kind){
  run.recruitment={kind,nodeId:run.active.id};
  const offers=recruitmentOffers(run,rosterSource(),kind);
  if(!offers.length){finishRecruitment();return;}
  screen='recruit';run.screen=screen;save();render();
}
function finishRecruitment(){const next=finalizeRecruitment(run);if(!next)return;team=[];if(next==='victory'){endRun('victory');return;}screen=next;save();render();}
function mapView(){const realm=REALMS[run.realms[run.act]],nodes=availableNodes(run),boss=byId(realm.boss),total=8;
  const x=n=>n.type==='boss'?360:[190,360,530][n.lane], y=n=>65+n.row*73;
  let paths='';for(const row of run.map.slice(0,-1))for(const n of row)for(const next of run.map[n.row+1])if(next.type==='boss'||Math.abs(n.lane-next.lane)<=1){const visited=run.visited.includes(n.id)&&run.visited.includes(next.id),active=run.visited.includes(n.id)&&nodes.some(a=>a.id===next.id);paths+=`<path d="M${x(n)} ${y(n)+25} C${x(n)} ${y(n)+43},${x(next)} ${y(next)-43},${x(next)} ${y(next)-25}" class="map-path ${visited?'traveled':active?'possible':''}"/>`;}
  return `<section class="page-heading"><div><p class="eyebrow">ACT ${String(run.act+1).padStart(2,'0')} <span class="dot-divider">·</span> ${run.realms[run.act].toUpperCase()} REALM</p><h1>${realm.name}</h1><p>${realm.subtitle}</p></div><div class="heading-aside"><span class="status-dot pulse"></span> Choose your next encounter<small>${run.row+1} / ${total} encounters completed</small></div></section><div class="map-layout"><section class="map-panel panel"><div class="map-top"><span>${icon('map',15)} EXPEDITION MAP</span><button data-action="new-run">New expedition ${icon('reroll',14)}</button></div><div class="map-canvas" style="--realm:${realm.color}"><div class="map-watermark">✧</div><svg class="map-svg" viewBox="0 0 720 665" aria-hidden="true">${paths}<path d="M360 30 L360 40" class="map-path traveled"/><text x="360" y="20" class="map-entry">RIFT ENTRANCE</text></svg>${run.map.flat().map(n=>{const type=NODE_TYPES[n.type],available=run.active?n.id===run.active.id:nodes.some(v=>v.id===n.id),visited=run.visited.includes(n.id),current=run.row===n.row&&run.lane===n.lane,unplayable=available&&['fight','elite','boss'].includes(n.type)&&!hasLegalLineup(run,pool(),n);return `<button class="map-node ${available?'available':''} ${visited?'visited':''} ${current?'current':''} ${n.type==='boss'?'boss-node':''} ${unplayable?'blocked-node':''}" style="left:${x(n)/7.2}%;top:${y(n)/6.65}%;--node-color:${type.color}" data-node="${n.id}" ${!available?'disabled':''} aria-label="${type.name}, encounter ${n.row+1}, path ${n.lane+1}${available?(unplayable?', no legal lineup with this roster':', available'):''}" title="${type.name}${['fight','elite','boss'].includes(n.type)?` · ${n.mana+(n.modifier==='Rift Surge'?5:0)} mana · ${n.rule}${n.modifier?' · '+n.modifier:''}`:''}"><span>${visited?icon('check',20):type.icon}</span>${unplayable?'<small>NO LEGAL TEAM</small>':n.type==='boss'?'<small>GUARDIAN</small>':available?'<small>CHOOSE PATH</small>':''}${n.modifier&&!visited?'<i class="modifier-dot"></i>':''}</button>`;}).join('')}</div><div class="map-bottom"><span>Connected paths are available. Marked encounters need a reroll to field a legal team.</span><span><i class="modifier-dot"></i> Rift modifier</span></div></section><aside class="map-sidebar"><section class="guardian-card panel"><div class="panel-label"><span class="red-dot"></span> ACT GUARDIAN</div><div class="guardian-art"><img src="./assets/cards/${boss.id}.jpg" alt="${safe(boss.name)}"><div class="guardian-art-shade"></div><span class="guardian-seal">♛</span></div><div class="guardian-copy"><p>${safe(byId(realm.archon).name)}’S GUARDIAN</p><h2>${safe(boss.name)}</h2><span>A legendary presence guards the way forward.</span><div class="guardian-rewards"><span>${icon('shard',15)} 40–55 shards</span><span>${icon('token',15)} +1 token</span></div></div></section><section class="legend panel"><p class="panel-label">KNOW YOUR PATH</p>${Object.entries(NODE_TYPES).map(([key,n])=>`<div class="legend-item"><span class="legend-icon" style="color:${n.color}">${n.icon}</span><span><strong>${n.name}</strong><small>${{fight:'8–14 shards',elite:'18–26 shards · bonus rewards',shop:'Recruit cards or buy an advantage',mystery:'An uncertain opportunity',camp:'Choose a buff or a Rift Token',boss:'The final encounter of this act'}[key]}</small></span></div>`).join('')}</section><div class="field-note"><span>✧</span><p><strong>Every battle is a fresh start.</strong>Your units return at full health. Save Rift Tokens for the paths that fight back.</p></div></aside></div>`;}
function portrait(c,extra=''){return `<img class="card-portrait ${extra}" src="./assets/cards/${c.id}.jpg" alt="${safe(c.name)}" loading="lazy" data-remote="${imageURL(c)}">`;}
function stats(c){return `<span class="stat melee" title="Melee attack">${icon('sword',12)}${c.attack}</span><span class="stat magic" title="Magic attack">✦ ${c.magic}</span><span class="stat ranged" title="Ranged attack">◎ ${c.ranged}</span><span class="stat" title="Speed">${icon('speed',12)}${c.speed}</span><span class="stat armor" title="Armor">${icon('shield',12)}${c.armor}</span><span class="stat health" title="Health">${icon('heart',12)}${c.health}</span>`;}
function cardView(c,options={}){const selected=options.roster?run.rosterIds.includes(c.id):options.draft&&team.some(t=>t.id===c.id),g=options.graft?grafted(c):c,disabled=options.roster?!selected&&run.rosterIds.length>=STARTER_LIMIT:options.draft&&(!eligible(g,run.active.rule)||!selected&&(team.length>=6||g.mana+team.reduce((s,t)=>s+grafted(t).mana,archon.mana)>cap()));
 return `<button class="unit-card rarity-${c.rarity} ${selected&&(options.draft||options.roster)?'selected':''} ${disabled?'unavailable':''}" style="--element:${COLORS[c.element]}" data-${options.roster?'roster-card':options.draft?'card':options.select?'archon':'detail'}="${c.id}" ${disabled?'disabled':''} aria-label="${selected?'Remove':'Select'} ${safe(c.name)}, ${g.mana} mana"><div class="card-art">${portrait(c)}<span class="mana-orb">${g.mana}</span><span class="card-element" title="${c.element}">${SYMBOLS[c.element]}</span>${selected&&(options.draft||options.roster)?`<span class="selected-stamp">${icon('check',18)}</span>`:''}</div><div class="card-copy"><small>${c.element} <span>LV ${c.level} · ${RARITIES[c.rarity]}</span></small><h3>${safe(c.name)}</h3><div class="card-stats">${stats(g)}</div><div class="card-abilities">${g.abilities.length?g.abilities.map(a=>`<span title="${safe(a)}">${safe(a)}</span>`).join(''):'<span class="no-ability">No base ability</span>'}</div></div></button>`;}
function draftView(){const n=run.active,enemy=enemyLineup(),mana=team.reduce((s,c)=>s+grafted(c).mana,archon?.mana||0),validation=validateTeam(team.map(grafted),archon,cap(),n.rule,n.modifier,paired),unplayable=!suggestLineup(run,pool(),enemy),show=monsters().filter(c=>filter==='all'||filter==='melee'&&c.attack||filter==='magic'&&c.magic||filter==='ranged'&&c.ranged).filter(c=>c.name.toLowerCase().includes(search.toLowerCase()));return `<section class="page-heading compact"><div><button class="text-button" data-action="back-map">${icon('back',14)} Expedition map</button><h1>Prepare for ${n.type==='boss'?'the Guardian':n.type==='elite'?'an elite encounter':'battle'}</h1><p>Choose from your expedition roster. Each unit enters at full health.</p></div><span class="encounter-number">ENCOUNTER ${n.row+1} <span>/ 08</span></span></section><div class="rules-banner"><div>${icon('book',23)}<span><small>ACTIVE RULESET</small><strong>${n.rule}</strong><p>${RULES[n.rule]}</p></span></div>${n.modifier?`<div class="rift-rule"><span>✧</span><span><small>RIFT MODIFIER</small><strong>${n.modifier}</strong><p>${MODIFIERS[n.modifier]}</p></span></div>`:''}<div class="mana-cap"><span class="mana-orb">${cap()}</span><span><small>MANA CAP</small><strong>${mana} <span>/ ${cap()}</span></strong><div class="mana-track"><i style="width:${Math.min(100,mana/cap()*100)}%"></i></div></span></div></div><div class="draft-layout"><div class="draft-main"><section class="team-panel panel"><div class="section-title"><span><b>YOUR LINEUP</b><small>${team.length} / 6 units</small></span><div><button class="text-button" data-action="clear-team">Clear</button><button class="mini-button" data-action="auto-team">${icon('speed',13)} Suggest lineup</button></div></div><div class="archon-line"><button class="archon-chip" data-action="choose-archon">${archon?portrait(archon):''}<span><small>YOUR ARCHON</small><strong>${safe(archon?.name||'Choose an Archon')}</strong><span>${archon?`${archon.element} · ${archon.mana} mana`:''}</span></span><span class="change">Change ${icon('reroll',12)}</span></button>${['Dragon','Neutral'].includes(archon?.element)?`<label class="pair-select">Paired element<select id="paired-element">${['Fire','Water','Earth','Life','Death'].map(e=>`<option ${paired===e?'selected':''}>${e}</option>`).join('')}</select></label>`:`<span class="archon-buff">${archonBuff(archon)}</span>`}</div><div class="team-slots">${Array.from({length:6},(_,i)=>{const c=team[i];return `<div class="team-slot ${c?'filled':''} ${i===1&&n.modifier==='Fractured Loadout'?'fractured':''}"><div class="slot-top"><span>${String(i+1).padStart(2,'0')}</span><small>${i===0?'FRONTLINE':i===1&&n.modifier==='Fractured Loadout'?'COMMON ONLY':'BACKLINE'}</small></div>${c?`<button data-remove="${i}" class="slot-card" title="Remove ${safe(c.name)}">${portrait(c)}<div><b>${safe(c.name)}</b><span>${grafted(c).mana} mana</span></div><span class="remove-card">×</span></button><div class="slot-controls"><button data-move="${i}" ${i===0?'disabled':''} aria-label="Move ${safe(c.name)} forward">‹</button><button data-graft="${c.id}" title="Graft an ability">${run.grafts[c.id]?'✧':'+'}</button><button data-move-right="${i}" ${i===team.length-1?'disabled':''} aria-label="Move ${safe(c.name)} backward">›</button></div>`:`<div class="empty-slot"><span>+</span><small>Select a unit</small></div>`}</div>`;}).join('')}</div></section><section class="collection-panel panel"><div class="section-title"><span><b>EXPEDITION ROSTER</b><small>${show.length} compatible units</small></span><label class="search-field"><span>⌕</span><input id="card-search" value="${safe(search)}" placeholder="Find a unit…" aria-label="Find a unit"></label></div><div class="filter-row">${[['all','All units'],['melee','Melee'],['ranged','Ranged'],['magic','Magic']].map(([k,label])=>`<button data-filter="${k}" class="filter-button ${filter===k?'active':''}">${label}</button>`).join('')}<span>${archon?.element} + Neutral${archon?.secondary?' + '+archon.secondary:''}</span></div><div class="card-grid">${show.map(c=>cardView(c,{draft:true,graft:true})).join('')||'<div class="empty-message">No units match these filters.</div>'}</div></section></div><aside class="battle-sidebar"><section class="enemy-preview panel"><p class="panel-label">${n.type==='boss'?'GUARDIAN':'OPPONENT'} INTEL</p><h2>${safe(enemy.archon.name)}</h2><p>${enemy.team.length} units <span>·</span> ${enemy.team.reduce((s,c)=>s+c.mana,enemy.archon.mana)} mana</p><div class="enemy-mini-team">${enemy.team.map(c=>`<div>${portrait(c)}<span>${safe(c.name)}</span><small>${c.mana} MANA · ${c.health} HP</small></div>`).join('')}</div></section><section class="battle-ready panel"><div class="reward-preview"><small>POTENTIAL REWARD</small><strong>${icon('shard',18)} ${n.type==='boss'?'40–55':n.type==='elite'?'18–26':'8–14'} <span>Rift Shards</span></strong>${n.attempt&&run.penalty?`<p>${Math.round((n.type==='boss'?Math.min(.2,run.penalty):run.penalty)*100)}% reroll penalty</p>`:''}</div><button class="button primary full" data-action="battle" ${validation?'disabled':''}>${icon('sword')} Enter battle ${icon('arrow')}</button><p class="validation">${unplayable?'No legal lineup can enter this encounter with your roster.':validation||'Your lineup is ready. Good luck, explorer.'}</p>${unplayable?`<button class="button secondary full" data-action="reroll-unplayable" ${run.tokens<1?'disabled':''}>${run.tokens<1?'No Rift Tokens remain':'Reroll this encounter · 1 Rift Token'}</button>${run.tokens<1?'<button class="button muted full" data-action="end-run">End expedition</button>':''}`:''}${run.mode==='collection'?'<p class="simulation-note">Preview combat: advanced owned-card abilities and Archon tactics may not trigger. Check card details in Collection.</p>':''}</section><div class="field-note"><span>✧</span><p>Melee units attack from the front unless an ability allows otherwise. Keep your ranged attackers behind a tank.</p></div></aside></div>`;}
function archonBuff(c){if(!c)return '';const labels={attack:'melee',ranged:'ranged',magic:'magic',speed:'speed',health:'health',armor:'armor'};return Object.entries(labels).filter(([k])=>c[k]).map(([k,v])=>`${c[k]>0?'+':''}${c[k]} ${v}`).concat(c.abilities||[]).join(' · ')||'Element access';}
function enemyLineup(){return enemyFor(run,foundation,cards);}
function replayView(){const pending=run.pending,event=pending.events[Math.min(replayIndex,pending.events.length-1)],enemy=run.enemy;return `<section class="page-heading compact"><div><p class="eyebrow">THE RIFT ARENA</p><h1>Clash beyond the veil</h1></div><div class="replay-round"><span>ROUND</span><strong id="round-number">${event.round||1}</strong></div></section><section class="arena panel"><div class="arena-team enemy-side"><div class="arena-team-label"><span>${safe(enemy.archon.name)}</span><small>OPPONENT</small></div><div id="enemy-combatants" class="combatants">${combatants(enemy.team,event.teams[1],event)}</div></div><div class="arena-divider"><span>⚔</span><p id="event-text">${safe(event.text)}</p><small id="combat-rule">${event.rule}</small></div><div class="arena-team friendly-side"><div id="friendly-combatants" class="combatants">${combatants(run.friendly,event.teams[0],event)}</div><div class="arena-team-label"><span>${safe(archon?.name||run.battleArchon.name)}</span><small>YOUR TEAM</small></div></div><div class="replay-controls"><span id="replay-progress">${replayIndex+1} / ${pending.events.length} events</span><div><button class="mini-button" data-action="replay-toggle">${icon('pause',13)} Pause / play</button><button class="mini-button" data-action="replay-speed">${replaySpeed}× speed</button><button class="mini-button" data-action="skip">Skip to result ${icon('arrow',13)}</button></div></div></section><section class="combat-log panel"><p class="panel-label">BATTLE LOG <span>Real card stats · local simulator</span></p><div id="battle-log">${pending.events.slice(Math.max(0,replayIndex-5),replayIndex+1).map(e=>`<p class="log-${e.type}"><small>R${e.round||1}</small>${safe(e.text)}</p>`).join('')}</div></section>`;}
function combatants(original,state,event){return original.map((c,i)=>{const s=state[i];return `<div class="combat-card ${s.dead?'dead':''} ${event.actor===s.uid?'attacking':''} ${event.target===s.uid?'hit':''}">${portrait(c)}<div class="combat-copy"><b>${safe(c.name)}</b><div class="combat-stats"><span class="health">${icon('heart',12)}${s.health}</span><span class="armor">${icon('shield',12)}${s.armor}</span><span>${icon('sword',12)}${s.attack+s.magic+s.ranged}</span></div><div class="health-track"><i style="width:${Math.max(0,s.health/s.maxHealth)*100}%"></i></div></div>${s.dead?'<span class="fallen-label">FALLEN</span>':''}</div>`;}).join('');}
function startReplay(){replayTimer=setInterval(()=>{if(screen!=='replay'||modal)return;replayIndex++;if(replayIndex>=run.pending.events.length){finishReplay();return;}const event=run.pending.events[replayIndex];$('#round-number').textContent=event.round||1;$('#event-text').textContent=event.text;$('#combat-rule').textContent=event.rule;$('#enemy-combatants').innerHTML=combatants(run.enemy.team,event.teams[1],event);$('#friendly-combatants').innerHTML=combatants(run.friendly,event.teams[0],event);$('#battle-log').innerHTML=run.pending.events.slice(Math.max(0,replayIndex-5),replayIndex+1).map(e=>`<p class="log-${e.type}"><small>R${e.round||1}</small>${safe(e.text)}</p>`).join('');$('#replay-progress').textContent=`${replayIndex+1} / ${run.pending.events.length} events`;bindImages();},650/replaySpeed);}
function finishReplay(){clearInterval(replayTimer);replayTimer=null;if(run.pending.winner!=='friendly'&&run.tokens===0){endRun('defeat');return;}screen='result';run.screen=screen;save();render();}
function resultView(){const victory=run.pending.winner==='friendly',reward=rewardFor(run.active,run);return `<section class="result-screen"><div class="result-seal ${victory?'win':'loss'}">${victory?'✧':'♜'}</div><p class="eyebrow">${run.pending.rounds} ROUNDS <span class="dot-divider">·</span> ${NODE_TYPES[run.active.type].name.toUpperCase()} ENCOUNTER</p><h1>${victory?'The path is yours.':'The rift fights back.'}</h1><p>${victory?'Your team stands victorious. Gather your rewards and journey onward.':run.active.modifier==='Bloodprice Shard'?'Bloodprice consumed one token on defeat. Spend another to regenerate this encounter.':'A lost battle is a chance to change your approach. Reroll for a new enemy, ruleset, and mana cap.'}</p>${victory?`<div class="reward-cards"><div class="reward-box">${icon('shard',30)}<strong>+${reward.shards}</strong><span>Rift Shards</span>${reward.penalty?`<small>${Math.round(reward.penalty*100)}% penalty · base ${reward.base}</small>`:'<small>Victory reward</small>'}</div>${reward.token?`<div class="reward-box purple">${icon('token',30)}<strong>+1</strong><span>Rift Token</span><small>Another chance in the rift</small></div>`:''}${reward.ability?`<div class="reward-box epic"><span class="reward-glyph">✦</span><strong>${reward.ability}</strong><span>${RARITIES[TOKENS[reward.ability].tier]} ability token</span><small>${TOKENS[reward.ability].scope==='act'?'Lasts through the act':'Single battle'}</small></div>`:''}</div><button class="button primary" data-action="claim">Claim & continue ${icon('arrow')}</button>`:`<div class="defeat-tokens">${icon('token',30)}<strong>${run.tokens}</strong><span>Rift Tokens remaining</span></div><div class="result-actions"><button class="button primary" data-action="reroll" ${run.tokens<1?'disabled':''}>${icon('reroll')} Reroll encounter <span>−1 token</span></button><button class="button secondary" data-action="end-run">End expedition</button></div><small class="penalty-note">Next reroll: ${Math.min(run.active.type==='boss'?20:40,(run.rerolls+1)*10)}% shard reward reduction${run.active.modifier==='Corrupted Mana'?' · +2 mana cap':''}</small>`}<button class="text-button battle-report" data-action="battle-report">Review battle log ${icon('book',14)}</button></section>`;}
function shopView(){return `<section class="page-heading"><div><p class="eyebrow">A REFUGE BETWEEN WORLDS</p><h1>The Rift Merchant</h1><p>A small advantage can change the course of an expedition.</p></div><button class="button secondary" data-action="leave-node">Return to the path ${icon('arrow')}</button></section><div class="shop-intro panel"><span>◇</span><p>Every journey needs companions.<br><em>And a little luck.</em></p><div>${icon('shard',28)}<strong>${run.shards}</strong><small>SHARDS TO SPEND</small></div></div><section class="merchant-recruits"><div class="section-title"><span><b>TRAVELING COMPANIONS</b><small>Permanent additions to this expedition</small></span></div><div class="recruit-grid">${recruitmentCards('merchant')||'<p class="fine-print">Your roster already includes every available companion.</p>'}</div></section><div class="shop-grid">${[{name:'Rift Token',price:40,tier:2,description:'Regenerate a lost encounter with a new enemy, ruleset, and mana cap.',scope:'A second chance',glyph:'◈'},...Object.entries(TOKENS).map(([name,t])=>({name,...t,scope:t.scope==='act'?'Lasts through this act':t.scope==='run'?'Lasts through the run':'Single battle',glyph:'✦'})),{name:'Mana Artifact',price:25,tier:2,description:'Increase your next battle’s mana cap by 4. Consumed after the battle.',scope:'Next battle only',glyph:'◆'}].map(item=>`<article class="shop-item panel rarity-${item.tier}"><div class="shop-item-heading"><span class="item-glyph">${item.glyph}</span><small>${item.name.includes('Token')||item.name==='Mana Artifact'?'RIFT RESOURCE':RARITIES[item.tier].toUpperCase()+' ABILITY'}</small></div><h2>${item.name}</h2><p>${item.description}</p><span class="scope-label">${item.scope}</span><button class="button ${run.shards>=item.price?'secondary':'muted'} full" data-buy="${item.name}" ${run.shards<item.price?'disabled':''}>${icon('shard',16)} ${item.price} shards <span>${run.shards>=item.price?'Purchase':'Not enough shards'}</span></button></article>`).join('')}</div>`;}
function campView(){const inter=screen==='intermission';return `<section class="camp-screen"><div class="camp-symbol">♨</div><p class="eyebrow">${inter?'A GUARDIAN FALLS. A NEW REALM WAITS.':'A QUIET MOMENT IN THE RIFT'}</p><h1>${inter?'Between worlds.':'Make camp.'}</h1><p>${inter?'Carry one advantage into the next act.':'No wounds to mend. Use this stop to prepare for what lies ahead.'}<br>Choose one boon before continuing.</p><div class="camp-choices"><button class="panel camp-choice" data-camp="token">${icon('token',32)}<h2>Bank a second chance</h2><p>Gain 1 Rift Token.</p><small>BUYBACK RESOURCE</small></button><button class="panel camp-choice" data-camp="mana">${icon('mana',32)}<h2>Attune the rift</h2><p>+2 mana to every remaining battle.</p><small>RUN-LONG ARTIFACT</small></button><button class="panel camp-choice" data-camp="ability"><span class="camp-glyph">✦</span><h2>Learn a new trick</h2><p>Gain a free ${inter?'Blast':'Sneak'} ability token.</p><small>SINGLE-BATTLE GRAFT</small></button></div></section>`;}
function mysteryView(){const outcome=mysteryOutcome(run.active);return `<section class="mystery-screen"><div class="mystery-glyph">?</div><p class="eyebrow">AN UNKNOWN ENCOUNTER</p><h1>${{shards:'A forgotten cache.',token:'An echo of another life.',fight:'Something in the shadows.',shop:'An unexpected traveler.',recruit:'A fellow wanderer.'}[outcome]}</h1><p>${{shards:'Among the ruins, a faint glow reveals a handful of Rift Shards. Fortune favors the curious.',token:'A traveler left behind a token. Their journey ended here; yours has a little further to go.',fight:'The passage seemed empty. A hostile team steps out of the shifting fog.',shop:'A merchant appears where no merchant should be. Their wares are real enough.',recruit:'Another traveler seeks a way through the rift. Invite a companion to join your expedition.'}[outcome]}</p><button class="button primary" data-mystery="${outcome}">${{shards:'Gather the shards',token:'Take the token',fight:'Prepare your team',shop:'Browse their wares',recruit:'Meet the travelers'}[outcome]} ${icon('arrow')}</button></section>`;}
function endView(){const won=run.status==='victory';return `<section class="end-screen"><div class="result-seal ${won?'win':'loss'}">${won?'✧':'◇'}</div><p class="eyebrow">EXPEDITION ${won?'COMPLETE':'CONCLUDED'}</p><h1>${won?'A Rift Walker is born.':'Every path teaches.'}</h1><p>${won?'Three realms. Three Guardians. You walked through them all.':'The rift will open again. Bring what you’ve learned into your next expedition.'}</p><div class="end-stats"><div><strong>${run.wins}</strong><span>BATTLES WON</span></div><div><strong>${run.guardians}</strong><span>GUARDIANS DEFEATED</span></div><div><strong>${run.earned}</strong><span>SHARDS EARNED</span></div><div><strong>${run.rerolls}</strong><span>RIFT REROLLS</span></div></div>${run.mode==='guest'?`<p class="unlock-note">${profile.completed===1?'Water unlocked · Marlai Singariel joins your trial Archons.':profile.completed===2?'Death unlocked · Thalgrimore joins your trial Archons.':profile.completed===3?'Dragon pairing unlocked · select a second element with Dragon Archons from your own collection.':`Guest expeditions completed: ${profile.completed}.`}</p>`:''}<button class="button primary" data-action="begin">Start a new expedition ${icon('arrow')}</button><button class="text-button" data-tab="journal">View chronicle ${icon('book',14)}</button></section>`;}
function collectionView(){const source=collection?.cards||foundation;const filtered=source.filter(c=>filter==='all'||c.element===filter).filter(c=>c.name.toLowerCase().includes(search.toLowerCase()));return `<section class="page-heading"><div><p class="eyebrow">YOUR STRATEGY STARTS HERE</p><h1>${collection?safe(collection.username)+'’s collection':'The Foundation collection'}</h1><p>${collection?'Public native-Hive cards, joined to the official stats snapshot.':`${foundation.length} official cards · ${foundation.filter(c=>c.type==='Summoner').length} Archons · live API snapshot`}</p></div><button class="button secondary" data-action="import">${icon('wallet')} Look up a collection</button></section><section class="panel full-collection"><div class="collection-toolbar"><div class="filter-row">${['all','Fire','Water','Earth','Life','Death','Dragon','Neutral'].map(e=>`<button class="filter-button ${filter===e?'active':''}" data-filter="${e}">${e==='all'?'All cards':`${SYMBOLS[e]} ${e}`}</button>`).join('')}</div><label class="search-field"><span>⌕</span><input id="card-search" placeholder="Search collection…" value="${safe(search)}" aria-label="Search collection"></label></div><div class="card-grid collection-grid">${filtered.slice(collectionPage*48,(collectionPage+1)*48).map(c=>cardView(c)).join('')||'<div class="empty-message">No cards match these filters.</div>'}</div>${filtered.length>48?`<div class="pagination"><button class="mini-button" data-page="${collectionPage-1}" ${collectionPage===0?'disabled':''}>Previous</button><span>Page ${collectionPage+1} of ${Math.ceil(filtered.length/48)}</span><button class="mini-button" data-page="${collectionPage+1}" ${(collectionPage+1)*48>=filtered.length?'disabled':''}>Next</button></div>`:''}</section>`;}
function journalView(){const history=profile.runs||[],linked=readStore('riftwalker.linked-history.v1',[]);const runs=[...history,...linked].sort((a,b)=>b.ended-a.ended);return `<section class="page-heading"><div><p class="eyebrow">RECORDS FROM BEYOND THE VEIL</p><h1>The explorer’s chronicle</h1><p>Each expedition leaves a mark. Guest and collection records stay separate.</p></div><span class="chronicle-count">${runs.length} EXPEDITIONS</span></section><div class="chronicle-summary"><div class="panel"><span>GUEST EXPEDITIONS</span><strong>${profile.completed}</strong><small>Completion unlocks new trial Archons</small></div><div class="panel"><span>REALMS CONQUERED</span><strong>${runs.reduce((n,r)=>n+r.guardians,0)}</strong><small>Guardians defeated across all runs</small></div><div class="panel"><span>SHARDS COLLECTED</span><strong>${runs.reduce((n,r)=>n+r.earned,0)}</strong><small>Sandbox currency · no real DEC value</small></div></div><section class="panel chronicle-list">${runs.length?runs.map(r=>`<div class="chronicle-row"><span class="history-icon ${r.status==='victory'?'gold':''}">${r.status==='victory'?'✧':'◇'}</span><span><strong>${r.status==='victory'?'Rift conquered':'Expedition concluded'}</strong><small>${r.realms.join(' → ')} · ${r.mode==='guest'?'Guest':safe(r.username)}</small></span><span>${r.wins} wins <small>${r.guardians} Guardians</small></span><span>${r.earned} shards<small>${new Date(r.ended).toLocaleDateString('en-GB')}</small></span></div>`).join(''):'<div class="empty-message"><span>✧</span><h2>Your story is still unwritten.</h2><p>Finish an expedition to record your first journey.</p><button class="button secondary" data-action="begin">Enter the rift</button></div>'}</section>`;}
function modalView(){let content='';if(modal.type==='guide')content=`<p class="eyebrow">THE EXPLORER’S FIELD GUIDE</p><h2>Walk into the unknown.</h2><div class="guide-grid"><div><b>01 · Build your expedition roster</b><p>Start with up to 12 cards, including an Archon and compatible units. Recruit cards through battle rewards, merchants, and events. Your roster persists through all three acts. Each act has eight encounters. Select a glowing connected node. Other routes close behind you.</p></div><div><b>02 · Draft, then watch</b><p>Pick a roster Archon and up to six roster units within the mana cap. Frontline melee, backline ranged, and magic from any position. Arrow buttons reorder your lineup.</p></div><div><b>03 · Spend your chances wisely</b><p>Start with 3 Rift Tokens. After a defeat, spend one to regenerate the encounter. Rerolled wins lose 10%, 20%, 30%, then 40% of shards; Guardian penalties cap at 20%.</p></div><div><b>04 · Make your collection count</b><p>Shop for ability grafts and mana artifacts. Apply tokens using + under a drafted unit. Camps offer one boon. Every encounter resets combat health.</p></div></div><div class="guide-note"><strong>About this preview</strong><p>Uses real API card stats and a local combat simulator. It covers Foundation level-1 abilities and selected classic abilities; advanced interactions, tactical Archon choices, and complete official-engine parity remain unverified. Unsupported abilities are flagged in card details. Wallet verification and real DEC transactions are not enabled.</p></div><div class="sources"><a href="https://support.splinterlands.com/hc/en-us/articles/11780878408852-New-Player-Guide-Gameplay" target="_blank" rel="noopener">Official gameplay guide ↗</a><a href="https://api.splinterlands.com/doc/" target="_blank" rel="noopener">Official API ↗</a></div>`;
  if(modal.type==='import')content=`<p class="eyebrow">PLAY WITH YOUR OWN CARDS</p><h2>Find your Hive collection.</h2><p>Enter your Splinterlands username. Collection lookup is public and read only. No password, wallet signature, or private key is needed.</p><form id="import-form"><label class="input-label" for="username">HIVE USERNAME</label><div class="import-input"><span>@</span><input id="username" name="username" required pattern="[a-z][a-z0-9.\-]{2,15}" maxlength="16" placeholder="your-username" value="${safe(collection?.username||'')}" autocomplete="off" ${importBusy?'disabled':''}></div>${importError?`<p class="error" role="alert">${safe(importError)}</p>`:''}<button class="button primary full" ${importBusy?'disabled':''}>${importBusy?'Reading collection…':'Look up collection'} ${icon('arrow')}</button></form>${collection?`<div class="import-success">${icon('check')} ${collection.cards.length} unique cards found for ${safe(collection.username)}.</div><button class="button secondary full" data-action="begin-linked">Start a fresh collection expedition ${icon('arrow')}</button><button class="text-button forget-lookup" data-action="forget-lookup">Forget this lookup</button>`:''}<div class="guide-note"><p>Collection mode starts a fresh expedition. Guest progress does not transfer. Only playable native-Hive cards returned by the public API are eligible. Lookup identifies a collection; it does not verify ownership.</p></div>`;
  if(modal.type==='archon')content=`<p class="eyebrow">CHOOSE YOUR COMMANDER</p><h2>A different kind of power.</h2><p>Choose an Archon from your expedition roster. It determines your elements and counts toward the mana cap. Changing Archons clears your drafted lineup.</p><div class="archon-options">${archons().map(c=>`<button class="archon-option ${archon?.id===c.id?'selected':''}" data-archon="${c.id}" ${!unlocked(c.element)?'disabled':''}>${portrait(c)}<span><small style="color:${COLORS[c.element]}">${c.element}</small><strong>${safe(c.name)}</strong><span>${archonBuff(c)} · ${c.mana} mana</span>${!unlocked(c.element)?`<em>Complete ${c.element==='Water'?1:2} guest expedition${c.element==='Death'?'s':''} to unlock</em>`:''}</span>${archon?.id===c.id?icon('check'):icon('arrow')}</button>`).join('')}</div><p class="fine-print">Foundation has no Dragon Archon. Dragon pairing becomes available with an owned Dragon Archon.</p>`;
  if(modal.type==='detail'){const c=modal.card,unsupported=c.abilities.filter(a=>!SUPPORTED.has(a));content=`<div class="detail-layout"><div class="detail-art">${portrait(c)}</div><div><p class="eyebrow" style="color:${COLORS[c.element]}">${c.element} · ${RARITIES[c.rarity]} · LEVEL ${c.level}</p><h2>${safe(c.name)}</h2><p>${safe(c.subtype||c.type)}</p><div class="detail-stats">${stats(c)}</div><p>${c.mana} mana · ${c.type}</p><div class="detail-abilities">${c.abilities.map(a=>`<span>${safe(a)}</span>`).join('')||'No base abilities at this level.'}</div>${unsupported.length?`<div class="guide-note"><strong>Not simulated in this preview</strong><p>${unsupported.map(safe).join(', ')}. These abilities will not trigger in local combat.</p></div>`:''}<p class="fine-print">Stats come from the official Splinterlands API snapshot. Rift grafts and Archon buffs are applied only inside battles.</p></div></div>`;}
  if(modal.type==='inventory'||modal.type==='graft'){const target=modal.type==='graft'?team.find(c=>c.id===modal.cardId):null;content=`<p class="eyebrow">YOUR EXPEDITION SATCHEL</p><h2>${target?'Graft an ability':'Small things. Big advantages.'}</h2><p>${target?`Choose a token for ${safe(target.name)}. Only one graft per unit; natural abilities cannot be duplicated.`:'Apply an ability token with the + button beneath a unit in your battle lineup.'}</p><div class="token-list">${run?.inventory.length?run.inventory.map((t,i)=>`<button class="token-entry rarity-${TOKENS[t.name].tier}" data-use-token="${i}" ${!target||target.abilities.includes(t.name)||run.grafts[target.id]||t.name==='Resurgence'&&Object.values(run.grafts).some(g=>g.name==='Resurgence')?'disabled':''}><span>✦</span><div><strong>${t.name}</strong><small>${TOKENS[t.name].description}</small><em>${TOKENS[t.name].scope==='act'?'This act':TOKENS[t.name].scope==='run'?'This run':'One battle'}</em></div>${target?icon('arrow'):''}</button>`).join(''):'<div class="empty-message">Your satchel is empty. Visit a merchant or defeat an elite.</div>'}</div>${run&&Object.keys(run.grafts).length?`<div class="grafted-list"><b>ACTIVE GRAFTS</b>${Object.entries(run.grafts).map(([id,t])=>`<p>✧ ${safe(pool().find(c=>c.id===Number(id))?.name)} <span>${t.name} · ${t.scope}</span></p>`).join('')}</div>`:''}`;}
  if(modal.type==='roster')content=`<p class="eyebrow">YOUR EXPEDITION COMPANIONS</p><h2>${run.rosterIds.length} cards for the journey</h2><p>Your lineup changes each battle. This roster grows through recruitment; grafts stay on their cards.</p><div class="card-grid roster-dialog-grid">${pool().map(c=>cardView(c,{graft:true})).join('')}</div>`;
  if(modal.type==='report')content=`<p class="eyebrow">BATTLE RECORD</p><h2>${run.pending.winner==='friendly'?'Victory':'Defeat'} · ${run.pending.rounds} rounds</h2><div class="report-log">${run.pending.events.map(e=>`<p class="log-${e.type}"><small>R${e.round||1}</small>${safe(e.text)}</p>`).join('')}</div>`;
  if(modal.type==='new')content=`<p class="eyebrow">A NEW PATH</p><h2>Leave this expedition?</h2><p>Your current expedition will conclude and be recorded in the chronicle. A new guest expedition starts with 3 Rift Tokens and 0 shards.</p><div class="modal-actions"><button class="button secondary" data-action="close-modal">Keep exploring</button><button class="button primary" data-action="confirm-new">Start a new expedition</button></div>`;
  return `<div class="modal-backdrop"><section class="modal ${modal.type==='detail'?'detail-modal':''}" role="dialog" aria-modal="true" aria-label="${safe(modal.type==='import'?'Import collection':modal.type==='guide'?'Field guide':'Expedition dialog')}" tabindex="-1"><button class="modal-close icon-button" data-action="close-modal" aria-label="Close dialog">${icon('close',20)}</button>${content}</section></div>`;}
function begin(mode='guest'){if(run?.status==='active')endRun('abandoned',false);run=createRun(mode,Date.now(),mode==='collection'?collection.username:null);if(mode==='collection')run.collectionSnapshot=collection;run.rosterIds=starterRoster(rosterSource());run.rosterLocked=false;team=[];archon=null;filter='all';search='';collectionPage=0;screen='roster';tab='expedition';modal=null;run.screen=screen;save();render();}
function endRun(status='defeat',show=true){if(run.status!=='active')return;run.status=status;run.ended=Date.now();const record={status,mode:run.mode,username:run.username,realms:run.realms,wins:run.wins,guardians:run.guardians,earned:run.earned,rerolls:run.rerolls,ended:run.ended};if(run.mode==='guest'){if(status!=='abandoned')profile.completed++;profile.runs=[record,...profile.runs].slice(0,50);}else{const history=readStore('riftwalker.linked-history.v1',[]);try{localStorage.setItem('riftwalker.linked-history.v1',JSON.stringify([record,...history].slice(0,50)));}catch{}}run.screen='end';screen='end';save();if(show)render();}
function takeNode(id){if(run.active){if(run.active.id===id){screen='draft';run.screen=screen;save();render();}return;}const n=availableNodes(run).find(n=>n.id===id);if(!n)return;run.active=n;resetDraft();screen=['fight','elite','boss'].includes(n.type)?'draft':n.type==='camp'?'camp':n.type==='shop'?'shop':'mystery';run.screen=screen;save();render();}
function battle(){if(!run.rosterLocked||!run.rosterIds.includes(archon?.id)||team.some(c=>!run.rosterIds.includes(c.id))){toast('Choose your lineup from the expedition roster.');return;}const friendly=team.map(grafted),n=run.active;const error=validateTeam(friendly,archon,cap(),n.rule,n.modifier,paired);if(error){toast(error);return;}const enemy=enemyLineup();run.enemy=enemy;run.friendly=friendly;run.battleArchon=archon;run.pending=simulate({friendly,enemy:enemy.team,archon,enemyArchon:enemy.archon,rule:n.rule,modifier:n.modifier,seed:n.seed+449});run.battles++;run.nextMana=0;for(const c of friendly){const g=run.grafts[c.id];if(g&&(g.scope==='battle'||g.name==='Divine Shield'))delete run.grafts[c.id];}if(run.pending.winner!=='friendly'&&n.modifier==='Bloodprice Shard')run.tokens=Math.max(0,run.tokens-1);replayIndex=0;screen='replay';run.screen=screen;save();render();}
function claim(){if(!claimVictory(run))return;team=[];openRecruitment('reward');}
function buy(name){const price=name==='Rift Token'?40:name==='Mana Artifact'?25:TOKENS[name]?.price;if(price==null||run.shards<price)return;run.shards-=price;if(name==='Rift Token')run.tokens++;else if(name==='Mana Artifact')run.nextMana=(run.nextMana||0)+4;else run.inventory.push({name,scope:TOKENS[name].scope,act:run.act});save();render();toast(`${name} added to your expedition.`);}
async function importCollection(event){event.preventDefault();if(importBusy)return;const username=$('#username').value.trim().toLowerCase();importBusy=true;importError='';render();try{const response=await fetch(location.hostname.endsWith(".github.io")?`https://api.splinterlands.com/cards/collection/${encodeURIComponent(username)}`:`./api/collection/${encodeURIComponent(username)}`),data=await response.json();if(!response.ok)throw new Error(data.error||'Collection lookup failed.');const lookup=new Map(details.map(d=>[d.id,d]));const joined=new Map();for(const owned of data.cards){const d=lookup.get(Number(owned.card_detail_id));if(!d)continue;if(owned.delegated_to&&owned.delegated_to!==username||owned.market_listing_type||owned.owner&&owned.owner!==username&&owned.delegated_to!==username)continue;const level=ownedLevel(owned,d,settings),c=normalize(d,level);if(!joined.has(c.id)||joined.get(c.id).level<c.level)joined.set(c.id,c);}const imported=[...joined.values()];if(!imported.some(c=>c.type==='Summoner'))throw new Error('No available Archon found. Guest mode includes the five Foundation Archons.');collection={username,cards:imported,loaded:Date.now()};save();}catch(error){importError=error.message;}finally{importBusy=false;render();}}
function resume(){screen=run.rosterLocked?(run.screen||'map'):'roster';if(run.collectionSnapshot)collection=run.collectionSnapshot;archon=archons().find(c=>c.id===run.archonId)||run.battleArchon||archons().find(c=>unlocked(c.element));paired=run.paired||'Fire';team=(run.draft||[]).map(id=>pool().find(c=>c.id===id)).filter(Boolean);if(screen==='replay')screen='result';if(run.pending&&run.pending.winner!=='friendly'&&run.tokens===0){endRun('defeat');return;}tab='expedition';modal=null;render();if(run.rosterMigrated){run.rosterMigrated=false;save();toast('Your saved lineup and grafted cards now anchor your expedition roster.');}}
function saveDraft(){run.archonId=archon?.id;run.paired=paired;run.draft=team.map(c=>c.id);save();}
function action(name){if(name==='view-roster'){modal={type:'roster'};render();return;}if(name==='clear-roster'||name==='suggest-roster'){if(run.rosterLocked)return;run.rosterIds=name==='clear-roster'?[]:starterRoster(rosterSource());save();render();return;}if(name==='lock-roster'){if(run.rosterLocked)return;const error=rosterError(run.rosterIds,rosterSource());if(error){toast(error);return;}run.rosterLocked=true;resetDraft();screen='map';run.screen=screen;save();render();return;}if(name==='skip-recruit'){finishRecruitment();return;}if(name==='home'){tab='expedition';screen='welcome';render();return;}if(name==='guide'||name==='import'||name==='inventory'||name==='choose-archon'||name==='battle-report'){modal={type:{guide:'guide',import:'import',inventory:'inventory','choose-archon':'archon','battle-report':'report'}[name]};render();return;}if(name==='close-modal'){modal=null;render();return;}if(name==='begin'){if(run?.status==='active'){modal={type:'new'};render();}else begin();return;}if(name==='confirm-new'){begin();return;}if(name==='begin-linked'){begin('collection');return;}if(name==='forget-lookup'){collection=null;localStorage.removeItem('riftwalker.collection.v1');modal=null;render();return;}if(name==='resume'){resume();return;}if(name==='new-run'){modal={type:'new'};render();return;}if(name==='back-map'){screen='map';run.screen=screen;save();render();return;}if(name==='clear-team'){team=[];saveDraft();render();return;}if(name==='auto-team'){const suggestion=suggestLineup(run,pool(),enemyLineup());if(!suggestion){toast('No legal lineup can enter under this rule and mana cap.');return;}const switched=archon?.id!==suggestion.archon.id;archon=suggestion.archon;paired=suggestion.paired;team=suggestion.team.map(c=>pool().find(p=>p.id===c.id));saveDraft();render();if(switched)toast(`${archon.name} leads this suggested lineup.`);return;}if(name==='battle'){battle();return;}if(name==='skip'){finishReplay();return;}if(name==='replay-toggle'){if(replayTimer){clearInterval(replayTimer);replayTimer=null;}else startReplay();return;}if(name==='replay-speed'){replaySpeed=replaySpeed===1?2:replaySpeed===2?4:1;render();return;}if(name==='claim'){claim();return;}if(name==='reroll-unplayable'){if(screen!=='draft'||!run.active||run.tokens<1||suggestLineup(run,pool(),enemyLineup()))return;rerollNode(run);resetDraft();screen='draft';run.screen=screen;save();render();return;}if(name==='reroll'){if(run.tokens<1)return;rerollNode(run);resetDraft();screen='draft';run.screen=screen;save();render();return;}if(name==='end-run'){endRun();return;}if(name==='leave-node'){completeNode(run);screen='map';run.screen=screen;save();render();}}
function bindImages(){document.querySelectorAll('img[data-remote]').forEach(img=>{img.onerror=()=>{if(img.dataset.tried){img.style.opacity='.08';img.onerror=null;return;}img.dataset.tried='1';img.src=img.dataset.remote;};});}
function bind(){bindImages();document.querySelectorAll('[data-roster-card]').forEach(el=>el.onclick=()=>{if(run.rosterLocked)return;const id=Number(el.dataset.rosterCard);if(!rosterSource().some(c=>c.id===id))return;if(run.rosterIds.includes(id))run.rosterIds=run.rosterIds.filter(v=>v!==id);else if(run.rosterIds.length<STARTER_LIMIT)run.rosterIds.push(id);save();render();});document.querySelectorAll('[data-recruit]').forEach(el=>el.onclick=()=>{const kind=el.dataset.kind,id=Number(el.dataset.recruit);if(!recruitCard(run,rosterSource(),kind,id))return;if(kind==='merchant'){save();render();toast('A new companion joined your expedition.');}else finishRecruitment();});document.querySelectorAll('[data-action]').forEach(el=>el.onclick=()=>action(el.dataset.action));document.querySelectorAll('[data-tab]').forEach(el=>el.onclick=()=>{tab=el.dataset.tab;filter='all';search='';collectionPage=0;render();});document.querySelectorAll('[data-node]').forEach(el=>el.onclick=()=>takeNode(el.dataset.node));document.querySelectorAll('[data-card]').forEach(el=>el.onclick=()=>{const c=monsters().find(c=>c.id===Number(el.dataset.card));if(!c)return;if(team.some(t=>t.id===c.id))team=team.filter(t=>t.id!==c.id);else if(team.length<6)team.push(c);saveDraft();render();});document.querySelectorAll('[data-remove]').forEach(el=>el.onclick=()=>{team.splice(Number(el.dataset.remove),1);saveDraft();render();});document.querySelectorAll('[data-move]').forEach(el=>el.onclick=()=>{const i=Number(el.dataset.move);if(i>0)[team[i],team[i-1]]=[team[i-1],team[i]];saveDraft();render();});document.querySelectorAll('[data-move-right]').forEach(el=>el.onclick=()=>{const i=Number(el.dataset.moveRight);if(i<team.length-1)[team[i],team[i+1]]=[team[i+1],team[i]];saveDraft();render();});document.querySelectorAll('[data-filter]').forEach(el=>el.onclick=()=>{filter=el.dataset.filter;collectionPage=0;render();});document.querySelectorAll('[data-detail]').forEach(el=>el.onclick=()=>{modal={type:'detail',card:(tab==='collection'?(collection?.cards||foundation):sourcePool()).find(c=>c.id===Number(el.dataset.detail))};render();});document.querySelectorAll('[data-archon]').forEach(el=>el.onclick=()=>{setArchon(el.dataset.archon);modal=null;render();});document.querySelectorAll('[data-buy]').forEach(el=>el.onclick=()=>buy(el.dataset.buy));document.querySelectorAll('[data-page]').forEach(el=>el.onclick=()=>{collectionPage=Number(el.dataset.page);render();window.scrollTo(0,0);});document.querySelectorAll('[data-camp]').forEach(el=>el.onclick=()=>{if(!campBoon(run,el.dataset.camp,screen==='intermission'))return;screen=run.screen;save();render();});document.querySelectorAll('[data-mystery]').forEach(el=>el.onclick=()=>{const outcome=el.dataset.mystery;if(outcome==='recruit'){openRecruitment('event');return;}if(outcome==='fight'){screen='draft';}else if(outcome==='shop'){screen='shop';}else{if(outcome==='token')run.tokens++;else{const shards=8+Math.floor(rng(run.active.seed+2)()*25);run.shards+=shards;run.earned+=shards;toast(`Found ${shards} Rift Shards.`);}completeNode(run);screen='map';}run.screen=screen;save();render();});document.querySelectorAll('[data-graft]').forEach(el=>el.onclick=()=>{modal={type:'graft',cardId:Number(el.dataset.graft)};render();});document.querySelectorAll('[data-use-token]').forEach(el=>el.onclick=()=>{const c=team.find(c=>c.id===modal.cardId),t=run.inventory[Number(el.dataset.useToken)];if(!c||!t||c.abilities.includes(t.name)||run.grafts[c.id])return;if(t.name==='Heal'&&team.reduce((n,x)=>n+grafted(x).mana,archon.mana)+1>cap()){toast('Heal adds 1 mana. Make room in your lineup first.');return;}run.grafts[c.id]=t;run.inventory.splice(Number(el.dataset.useToken),1);modal=null;save();render();});if($('#import-form'))$('#import-form').onsubmit=importCollection;if($('#paired-element'))$('#paired-element').onchange=e=>{paired=e.target.value;team=[];saveDraft();render();};if($('#card-search'))$('#card-search').oninput=e=>{search=e.target.value;const cursor=e.target.selectionStart;render();const input=$('#card-search');input?.focus();input?.setSelectionRange(cursor,cursor);};if(modal){$('.modal')?.focus();$('.modal-backdrop').onclick=e=>{if(e.target.classList.contains('modal-backdrop'))action('close-modal');};}}
document.addEventListener('keydown',e=>{if(!modal)return;if(e.key==='Escape')action('close-modal');if(e.key==='Tab'){const focusable=[...$('.modal').querySelectorAll('button:not(:disabled),input:not(:disabled),select,a[href]')],first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&(document.activeElement===first||document.activeElement=== $('.modal'))){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}});
try{const [cardData,config]=await Promise.all([fetch('./data/cards.json').then(r=>r.json()),fetch('./data/settings.json').then(r=>r.json())]);details=cardData.filter(d=>(d.game_type==='splinterlands'||!d.game_type)&&isBattleCard(d));settings=config;cards=details.map(d=>normalize(d));foundation=cards.filter(c=>c.editions.split(',').some(e=>['15','16'].includes(e)));profile=readStore('riftwalker.guest.v1',{completed:0,runs:[]});collection=readStore('riftwalker.collection.v1',null);run=readStore('riftwalker.run.v1',null);if(run&&run.version!==1)run=null;const battleIds=new Set(details.map(d=>Number(d.id)));const cleanCollection=sanitizeCollection(collection,battleIds),cleanRun=sanitizeCollectionRun(run,battleIds);let cleaned=cleanCollection!==collection||cleanRun!==run;collection=cleanCollection;run=cleanRun;if(ensureRoster(run,rosterSource()))cleaned=true;if(cleaned)save();render();}catch(error){app.innerHTML=`<section class="loading"><h1>The rift could not open.</h1><p>${safe(error.message)}</p><p>Start the local server with <code>npm start</code>, then open http://localhost:4173.</p></section>`;}
